pub fn (mut listener NoopZwpPointerGestureHoldV1Listener) end(_proxy ZwpPointerGestureHoldV1, _serial u32, _time u32, _cancelled i32) {
}

struct ZwpPointerGestureHoldV1Sink {
mut:
	proxy    ZwpPointerGestureHoldV1
	listener ZwpPointerGestureHoldV1Listener = NoopZwpPointerGestureHoldV1Listener{}
}

fn (mut s ZwpPointerGestureHoldV1Sink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			serial := msg.arg_u32(0)!
			time := msg.arg_u32(1)!
			surface_id := msg.arg_id(2)!
			surface := wl.wl_surface_proxy(s.proxy.conn, surface_id)
			fingers := msg.arg_u32(3)!
			s.listener.begin(s.proxy, serial, time, surface, fingers)
		}
		1 {
			serial := msg.arg_u32(0)!
			time := msg.arg_u32(1)!
			cancelled := msg.arg_int(2)!
			s.listener.end(s.proxy, serial, time, cancelled)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives zwp_pointer_gesture_hold_v1 events.
pub fn (proxy &ZwpPointerGestureHoldV1) set_listener(listener ZwpPointerGestureHoldV1Listener) ! {
	proxy.conn.set_sink(proxy.id, ZwpPointerGestureHoldV1Sink{
		proxy:    *proxy
		listener: listener
	})!
}

pub fn (proxy &ZwpPointerGestureHoldV1) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// bind_zwp_pointer_gestures_v1 binds the zwp_pointer_gestures_v1 global to a typed proxy.
pub fn bind_zwp_pointer_gestures_v1(conn &wayland.Connection, global wayland.Global) !ZwpPointerGesturesV1 {
	version := if global.version < zwp_pointer_gestures_v1_desc.version {
		global.version
	} else {
		zwp_pointer_gestures_v1_desc.version
	}
	object := conn.bind_global(global, 'zwp_pointer_gestures_v1', version, &zwp_pointer_gestures_v1_desc)!
	return ZwpPointerGesturesV1{
		Object: object
	}
}
